from datetime import datetime, timezone, timedelta

HERE = Path(__file__).resolve().parent; CB04 = HERE.parent; B4 = CB04.parent; W3 = CB04 / "W3"; HYD = B4 / "Hydrology"
ROOT = B4 / "Deliverables"; DEST = None; MANIFEST = None          # DEST = the snapshot folder, set by set_dest()
OMAN = timezone(timedelta(hours=4)); PROJECT_FILE = "Block04_Deliverables.qgz"
VERSION_RE = re.compile(r"^(\d+) Deliverables (\d{8})$")
def now_oman(): return datetime.now(OMAN).strftime("%Y-%m-%d %H:%M")
def versions():
    ROOT.mkdir(exist_ok=True); out = []
    for p in ROOT.iterdir():
        m = VERSION_RE.match(p.name)
        if p.is_dir() and m: out.append((int(m.group(1)), p))
    return sorted(out)
def set_dest(p):
    global DEST, MANIFEST
    DEST = Path(p); MANIFEST = DEST / "MANIFEST.csv"; DEST.mkdir(parents=True, exist_ok=True)
def latest_version(create=True):
    v = versions()
    if v: return v[-1][1]
    if not create: return None
    p = ROOT / f"1 Deliverables {datetime.now(OMAN).strftime('%d%m%Y')}"; p.mkdir(parents=True); return p
def new_version():
    v = versions(); n = (v[-1][0] + 1) if v else 1
    p = ROOT / f"{n} Deliverables {datetime.now(OMAN).strftime('%d%m%Y')}"; p.mkdir(parents=True); return p
