# ---------------------------------------------------------------- helpers
def lp(p):
    s = str(p)
    return ("\\\\?\\" + os.path.abspath(s)) if (os.name == "nt" and len(s) > 240 and not s.startswith("\\\\?\\")) else s
def skip(rel, name): return any(fnmatch.fnmatch(name, p) or fnmatch.fnmatch(rel, p) for p in SKIP)
def excluded(rel, ex): return any(fnmatch.fnmatch(rel, p) for p in ex)
def sha1(p):
    h = hashlib.sha1()
    with open(lp(p), "rb") as f:
        for b in iter(lambda: f.read(1 << 20), b""): h.update(b)
    return h.hexdigest()
def pairs(e):
    """(source file, destination file) pairs of one spec entry"""
    src = Path(e["src"]); base = DEST / e["group"] / e["dest"]
    if e["kind"] == "file":
        if src.exists(): yield src, base
    elif e["kind"] == "shp":
        if src.parent.exists():
            for f in src.parent.iterdir():
                if f.is_file() and f.stem.lower() == src.stem.lower(): yield f, base.parent / f.name
    elif e["kind"] == "tree":
        if src.exists():
            for r, ds, fs in os.walk(src):
                for fn in fs:
                    p = Path(r) / fn; rel = p.relative_to(src).as_posix()
                    if skip(rel, fn) or excluded(rel, e["exclude"]): continue
                    yield p, base / rel
def load_manifest():
    rows = {}
    if MANIFEST.exists():
        with open(MANIFEST, newline="", encoding="utf-8") as f:
            for r in csv.DictReader(f): rows[r["dest"]] = r
    return rows
def save_manifest(rows):
    cols = ["group", "dest", "kind", "source", "bytes", "source_mtime", "sha1", "copied_at", "note"]
    with open(MANIFEST, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=cols); w.writeheader()
        for k in sorted(rows): w.writerow({c: rows[k].get(c, "") for c in cols})
def rel_dest(d): return d.relative_to(DEST).as_posix()
def changed(s, d):
    if not d.exists(): return True
    ss, ds = s.stat(), d.stat(); return ss.st_size != ds.st_size or abs(ss.st_mtime - ds.st_mtime) > 2

# ---------------------------------------------------------------- sync
def sync(dry=False, only=None):
    man = load_manifest(); now = now_oman(); stats = {}; problems = []
    for e in SPEC:
        if only and not e["group"].startswith(only): continue
        g = stats.setdefault(e["group"], dict(files=0, bytes=0, copied=0, copied_bytes=0, pointers=0))
        src = Path(e["src"])
        if e["kind"] == "pointer":
            key = f'{e["group"]}/{e["dest"]}'; ok = src.exists()
            man[key] = dict(group=e["group"], dest=key, kind="pointer", source=e["src"], bytes="", source_mtime="", sha1="", copied_at=now, note=e["note"] + ("" if ok else "  [NOT REACHABLE at sync time]"))
            g["pointers"] += 1
            if not ok: problems.append(f"pointer not reachable: {e['src']}")
            continue
        found = False
        for s, d in pairs(e):
            found = True; st = s.stat(); mb = st.st_size / 1e6; key = rel_dest(d)
            if e["group"] == "10 References" and mb > MAX_COPY_MB:
                man[key] = dict(group=e["group"], dest=key, kind="pointer", source=str(s), bytes=st.st_size, source_mtime=f"{st.st_mtime:.0f}", sha1="", copied_at=now, note=f"{mb:.0f} MB, above the {MAX_COPY_MB} MB copy limit: pointer. " + e["note"])
                g["pointers"] += 1; continue
            g["files"] += 1; g["bytes"] += st.st_size
            if changed(s, d):
                g["copied"] += 1; g["copied_bytes"] += st.st_size
                if dry: print(f"   would copy {mb:8.1f} MB  {key}"); continue
                d.parent.mkdir(parents=True, exist_ok=True)
                try: shutil.copy2(lp(s), lp(d))
                except Exception as ex: problems.append(f"copy failed: {s} -> {d}: {ex}"); continue
                man[key] = dict(group=e["group"], dest=key, kind=e["kind"], source=str(s), bytes=st.st_size, source_mtime=f"{st.st_mtime:.0f}", sha1=(sha1(s) if mb <= HASH_MAX_MB else ""), copied_at=now, note=e["note"])
            elif key not in man:
                man[key] = dict(group=e["group"], dest=key, kind=e["kind"], source=str(s), bytes=st.st_size, source_mtime=f"{st.st_mtime:.0f}", sha1=(sha1(s) if mb <= HASH_MAX_MB else ""), copied_at=now, note=e["note"])
        if not found: problems.append(f"source missing: {e['src']}  ({e['group']}/{e['dest']})")
    if not dry:
        save_manifest(man); write_readme(man, stats, now); write_sources(man, now); write_root_readme(now)
    for gname, g in stats.items(): print(f"{gname:30s} {g['files']:5d} files {g['bytes'] / 1e6:8.0f} MB   copied {g['copied']:5d} ({g['copied_bytes'] / 1e6:.0f} MB)   pointers {g['pointers']}")
    for p in problems: print("PROBLEM:", p)
    print(("dry run, nothing written" if dry else f"manifest {len(man)} rows -> {MANIFEST}"), "|", f"{sum(g['bytes'] for g in stats.values()) / 1e9:.2f} GB in the folder")
    return problems

# ---------------------------------------------------------------- prune: the SPEC is the truth for what belongs here
def prune():
    """Delete files under Deliverables that the current SPEC does not produce and drop their manifest rows. A copy whose
    source has disappeared is kept (and reported by --check), so nothing precious is lost by a prune."""
    man = load_manifest(); keep = {"MANIFEST.csv", "README.md", "10 References/SOURCES.md", PROJECT_FILE}
    spec_keys = set()
    for e in SPEC:
        if e["kind"] == "pointer": spec_keys.add(f'{e["group"]}/{e["dest"]}')
        else: spec_keys.update(rel_dest(d) for s, d in pairs(e))
    removed = 0
    for r, ds, fs in os.walk(DEST):
        for fn in fs:
            f = Path(r) / fn; key = rel_dest(f)
            if key in keep or key in spec_keys: continue
            row = man.get(key)
            if row is not None and row["kind"] != "pointer" and not Path(row["source"]).exists(): continue   # source gone: keep the copy
            os.remove(lp(f)); man.pop(key, None); removed += 1; print("   pruned", key)
    for key in [k for k, r in man.items() if r["kind"] == "pointer" and k not in spec_keys]: man.pop(key)
    for r, ds, fs in sorted(os.walk(DEST), key=lambda t: -len(t[0])):
        if r != str(DEST) and not os.listdir(r): os.rmdir(r)
    save_manifest(man); print(f"prune: {removed} file(s) removed")

# ---------------------------------------------------------------- check
def check():
    man = load_manifest(); bad = []
    if not man: print("no manifest: run the sync first"); return 1
    for key, r in man.items():
        if r["kind"] == "pointer":
            if not Path(r["source"]).exists(): bad.append(f"POINTER GONE   {r['source']}")
            continue
        s, d = Path(r["source"]), DEST / key
        if not s.exists(): bad.append(f"SOURCE GONE    {key}  (copy kept)"); continue
        if not os.path.exists(lp(d)): bad.append(f"COPY MISSING   {key}"); continue      # the copy may sit beyond 260 characters (long-path prefix)
        st = s.stat()
        if str(st.st_size) != str(r["bytes"]) or abs(st.st_mtime - float(r["source_mtime"] or 0)) > 2: bad.append(f"STALE          {key}  (source changed after the sync)")
    for e in SPEC:
        if e["kind"] in ("tree", "shp", "file"):
            for s, d in pairs(e):
                if rel_dest(d) not in man: bad.append(f"NEVER SYNCED   {rel_dest(d)}")
    for b in bad: print(b)
    print("deliverables check:", "OK" if not bad else f"{len(bad)} problem(s)")
    return 1 if bad else 0

# ---------------------------------------------------------------- the generated documents
def write_readme(man, stats, now):
    L = [f"# Block 04 deliverables, snapshot `{DEST.name}` (internal)", "", f"Generated {now} Oman time by `Claude Block 04/scripts/sync_deliverables.py`. One organised copy of everything the Block 04 work produced or relied on. "
         f"The sources of record stay in `Claude Block 04`, `W3`, `Hydrology` and on the server; this folder is refreshed from them, never edited. **Live report revision: {REV}.**", "",
         "Refresh after every substantive change (like the README files):", "", "```bash", 'python "Claude Block 04/scripts/sync_deliverables.py"', "```", "",
         "The mechanical test, which fails when a copy is stale, missing, or a new source file was never synced:", "", "```bash", 'python "Claude Block 04/scripts/sync_deliverables.py" --check', "```", "",
         "## The QGIS project", "",
         (f"`{PROJECT_FILE}` at the root of this snapshot holds every relevant layer of the folder in groups and subgroups (Dams, Channels and dykes, HEC-HMS model, Sediment, Background, Map figure layers) and every map layout of the report, all saved inside the project. "
          "Every path in it is relative and inside this snapshot; the only online layer is the Google satellite background, which needs an internet connection. Built by `Claude Block 04/scripts/build_deliverables_qgis.py` after the sync."
          if (DEST / PROJECT_FILE).exists() else "not built yet: run `Claude Block 04/scripts/build_deliverables_qgis.py` after the sync."), "",
         "| Folder | Files | MB | Contents |", "|---|---|---|---|"]
    groups = sorted({e["group"] for e in SPEC})
    for g in groups:
        st = stats.get(g, dict(files=0, bytes=0)); notes = [f"**{e['dest']}**" + (f": {e['note']}" if e["note"] else "") for e in SPEC if e["group"] == g and e["kind"] != "pointer"]
        L.append(f"| `{g}` | {st['files']} | {st['bytes'] / 1e6:.0f} | " + "<br>".join(notes) + " |")
    L += ["", "## Pointers (not copied)", "", "| Where | What | Why not copied |", "|---|---|---|"]
    for k in sorted(man):
        r = man[k]
        if r["kind"] == "pointer": L.append(f"| `{r['source']}` | {r['dest']} | {r['note']} |")
    L += ["", "## Rules", "", "- Only the live report revision is here; the superseded ones (R0 …) stay in `Claude Block 04/W3/report`. Iterations live in `W#` folders and are never overwritten.",
          "- `MANIFEST.csv` lists every file with its source path, size, source time, SHA-1 (files up to 64 MB) and the sync time. `10 References/SOURCES.md` lists where every external file came from.",
          "- The QGIS projects reference absolute paths (W: server and D:); they open on this machine with the server mounted, not elsewhere.",
          "- The HMS DSS results are reproducible with `09 Scripts/Claude Block 04 scripts/hms_compute_all.py` (about 2 h for the four basins); the model, terrain and every run definition are here."]
    (DEST / "README.md").write_text("\n".join(L), encoding="utf-8")
def write_root_readme(now):
    L = ["# Block 04 deliverables", "", f"Numbered snapshots of everything the Block 04 work produced or relied on, internal. The latest snapshot is the live one and is refreshed by "
         "`Claude Block 04/scripts/sync_deliverables.py`; an older snapshot is frozen the moment the next one is created (`--new-version`). Dates are Oman dates (ddmmyyyy). "
         f"Each snapshot has its own README, MANIFEST.csv and root QGIS project. Updated {now} Oman time.", "", "| Snapshot | State |", "|---|---|"]
    v = versions()
    for n, p in v: L.append(f"| `{p.name}` | {'live, refreshed by the sync' if p == v[-1][1] else 'frozen'} |")
    (ROOT / "README.md").write_text("\n".join(L), encoding="utf-8")
def write_sources(man, now):
    L = [f"# Sources of the references (generated {now})", "", "Every file under `10 References` and every pointer, with the path it was taken from. The 2331 server is read-only: nothing there was modified.", "",
         "| In this folder | Taken from | What it is | Synced |", "|---|---|---|---|"]
    for k in sorted(man):
        r = man[k]
        if r["group"] == "10 References" or r["kind"] == "pointer": L.append(f"| {r['dest']} | `{r['source']}` | {r['note']} | {r['copied_at']} |")
    (DEST / "10 References").mkdir(parents=True, exist_ok=True); (DEST / "10 References" / "SOURCES.md").write_text("\n".join(L), encoding="utf-8")

if __name__ == "__main__":
    a = sys.argv[1:]
    set_dest(new_version() if "--new-version" in a else latest_version()); print("snapshot:", DEST.name)
    if "--check" in a: sys.exit(check())
    if "--prune" in a: prune()
    only = a[a.index("--only") + 1] if "--only" in a else None
    sys.exit(1 if sync(dry="--dry" in a, only=only) else 0)
